def decrypt(text, shift):
    res = []
    for c in text:
        if 'a' <= c <= 'f':
            res.append(chr((ord(c) - ord('a') - shift) % 6 + ord('a')))
        elif '0' <= c <= '9':
            res.append(chr((ord(c) - ord('0') - shift) % 10 + ord('0')))
        else:
            res.append(c)
    return "".join(res)

cipher = "a26075b6ee7453f60f4b5f27"
for s in range(1, 10):
    print(f"Shift {s}: {decrypt(cipher, s)}")
